-- Update of 2026-11-12: the user's ownership remap (C:\HNH\report\kpis ownership remapping.xlsx) and weights by
-- hospital category.
-- 1. Owners: each KPI's Corporate owner is a role (CMOO, CMO, COO, CCO, CPEO, CHRO, VPF, IAD, S&G); co-owners are
--    emptied (the column stays for later use); the 16 hospital-level owner rows are removed.
-- 2. kpi_type follows the sheet's flag: Primary (headline) or Supporting ("secondary"); 24 KPIs change. Each changed
--    KPI's latest row is copied with only kpi_type changed.
-- 3. Weights: one profile per hospital category, 'category:<category>'. Each pillar takes the category's share
--    (Customer / Financial / Internal Process / Learning & Growth: Anchor & Protect 18 / 33 / 33 / 16 %, Ramp-Up &
--    Prove 21 / 27 / 36 / 16 %, Scale & Optimize 20 / 33 / 32 / 15 %), shared inside the pillar with a Primary KPI
--    at twice a Supporting one, in 0.25 % steps; parked KPIs get no row. The hospital profiles ('branch:<id>') and
--    the 'corporate' profile are removed: a hospital now takes its category's profile, and the corporate weight is
--    the average over the 8 hospitals (dim_bsc_kpi).
-- Needs the dbt models of 2026-11-12 (fact_bsc_weight reads category profiles) and BSC visual 1.1.7.0.
-- Applied with apply_bsc_config.ps1 -Update; insert-only, the latest row per key wins.


SELECT kpi_code, branch_id, l.1, l.2, now64(3), 'bsc-2026-11-12', 'hospital owner removed: the Corporate owner applies', 1
FROM (SELECT kpi_code, branch_id, argMax(tuple(owner, co_owners, is_deleted), changed_at) AS l FROM default.map_bsc_owner GROUP BY kpi_code, branch_id)
WHERE l.3 = 0 AND branch_id != 0;

SELECT kpi_code, l.1, l.2, l.3, l.4, if(kpi_code IN ('CUS_COMPLAINT_RATE', 'CUS_NEW_PATIENTS', 'CUS_OP_WAIT', 'CUS_PATIENT_RETENTION', 'CUS_PREMS', 'FIN_CONSUMABLES_RATIO', 'FIN_COST_TO_REVENUE', 'FIN_DAYS_INVENTORY', 'FIN_NET_COLLECTION', 'FIN_REVENUE_PER_DOCTOR', 'INT_ACTIVATED_BEDS', 'INT_ANCILLARY_UTILIZATION', 'INT_CLAIM_INITIAL_REJECTION', 'INT_DOCTOR_UTILIZATION', 'INT_ORDER_NOT_DONE', 'LRN_AUDIT_CLOSURE', 'LRN_MANDATORY_TRAINING', 'LRN_SAUDIZATION', 'LRN_STAFF_TO_BED'), 'Primary', 'Supporting'), l.6, l.7, l.8, l.9, l.10, l.11, l.12, l.13, l.14,
       now64(3), 'bsc-2026-11-12', 'kpi type from the ownership remap: Primary or Supporting (secondary)', 0
FROM (SELECT kpi_code, argMax(tuple(kpi_num, kpi_name, short_label, objective_code, kpi_type, direction, value_format, chart_hint, display_order, definition, status, target_source, value_source, detail_page, is_deleted), changed_at) AS l
      FROM default.map_bsc_kpi GROUP BY kpi_code)
WHERE l.15 = 0 AND kpi_code IN ('CUS_COMPLAINT_RATE', 'CUS_NEW_PATIENTS', 'CUS_NON_MOH_SHARE', 'CUS_OP_WAIT', 'CUS_PATIENT_RETENTION', 'CUS_PREMS', 'FIN_CONSUMABLES_RATIO', 'FIN_COST_TO_REVENUE', 'FIN_DAYS_INVENTORY', 'FIN_EBITDA_MARGIN', 'FIN_NET_COLLECTION', 'FIN_REVENUE_PER_BED', 'FIN_REVENUE_PER_DOCTOR', 'INT_ACTIVATED_BEDS', 'INT_ANCILLARY_UTILIZATION', 'INT_CLAIM_INITIAL_REJECTION', 'INT_DOCTOR_UTILIZATION', 'INT_HIGH_VALUE_CENSUS', 'INT_ORDER_NOT_DONE', 'INT_READMISSION_48H_CRITICAL', 'LRN_AUDIT_CLOSURE', 'LRN_MANDATORY_TRAINING', 'LRN_SAUDIZATION', 'LRN_STAFF_TO_BED');


SELECT profile, kpi_code, l.1, now64(3), 'bsc-2026-11-12', 'replaced by the category profiles', 1
FROM (SELECT profile, kpi_code, argMax(tuple(weight, is_deleted), changed_at) AS l FROM default.map_bsc_weight GROUP BY profile, kpi_code)
WHERE l.2 = 0 AND (startsWith(profile, 'branch:') OR profile = 'corporate');
